using System.Collections.Generic;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "ConfuseAction", menuName = "Data/Battle/Battle Actions/Purification Actions/Confuse Action")]
public class ConfuseAction : BattleAction
{
	[Header("Action Specifics")]
	[SerializeField]
	private CorruptAction corruptAction;

	[SerializeField]
	private PurifyAction purifyAction;

	[SerializeField]
	private int startingPurifyChanceAmount = 50;

	[SerializeField]
	private AchievementData bettingHighAchievementData;

	[SerializeField]
	private CriticalEffect criticalEffect;

	private PlayerEffects playerEffects => ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>();

	public override void AreaCastTargetAmount(List<GameObject> target, int amount, GameObject source)
	{
		int purifyChanceAmount = BeforeDefaultCastGetPurifyChanceAmount(amount, source);
		for (int i = 0; i < target.Count; i++)
		{
			DefaultCast(target[i], amount, source, purifyChanceAmount, areaConfuse: true);
		}
		ReferenceSingleton<MiscOmensHandler>.Instance.ResetWickedsCardOmenAction?.Invoke(source);
		purifyAction.ResetIgnoreResetWickedCard();
		corruptAction.ResetIgnoreResetWickedCard();
		AfterDefaultCast();
	}

	private void CheckBettingHighAustraAchievement(int amount, GameObject source, int purifyChanceAmount)
	{
		if (bettingHighAchievementData.CharacterCheck() && !bettingHighAchievementData.IsUnlocked() && ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source) && purifyChanceAmount == startingPurifyChanceAmount && amount >= bettingHighAchievementData.AchievementVariableAmount)
		{
			bettingHighAchievementData.Unlock();
		}
	}

	public bool IsPlayerConfuse(GameObject source)
	{
		bool result = false;
		if (ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source))
		{
			result = true;
		}
		return result;
	}

	public int GetPurifyChanceAmount(bool playerConfuse, bool description = false)
	{
		int result = startingPurifyChanceAmount;
		if (playerConfuse && !ReferenceSingleton<GameStateManager>.Instance.IsOnPlayerUnlockablesState)
		{
			int num = playerEffects.IsPlayerBrillianceGetAmount(description);
			result = Mathf.Min(100, startingPurifyChanceAmount + num);
		}
		return result;
	}

	public string GetBrillianceModifierText(bool playerConfuse)
	{
		if (ReferenceSingleton<GameStateManager>.Instance != null && ReferenceSingleton<GameStateManager>.Instance.IsOnPlayerUnlockablesState)
		{
			return startingPurifyChanceAmount.ToString();
		}
		if (playerConfuse)
		{
			int num = playerEffects.IsPlayerBrillianceGetAmount(activateFeedback: false);
			if (num > 0)
			{
				return startingPurifyChanceAmount + num + $"({startingPurifyChanceAmount}+{num})";
			}
			return startingPurifyChanceAmount.ToString();
		}
		return startingPurifyChanceAmount.ToString();
	}

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		int purifyChanceAmount = BeforeDefaultCastGetPurifyChanceAmount(amount, source);
		DefaultCast(target, amount, source, purifyChanceAmount, areaConfuse: false);
		AfterDefaultCast();
	}

	private int CheckConfuseModifyingEffectsAndGetPurifyChanceAmount(int purifyChanceAmount, GameObject source)
	{
		if (ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source))
		{
			int num = playerEffects.IsPlayerIridescentLightActivateItGetPurifyPercentageAmount();
			if (num > 0)
			{
				purifyChanceAmount = num;
			}
			else if (playerEffects.IsPlayerDoubtDispellerDecreaseEffect())
			{
				purifyChanceAmount = 100;
			}
		}
		return purifyChanceAmount;
	}

	private void DefaultCast(GameObject target, int amount, GameObject source, int purifyChanceAmount, bool areaConfuse)
	{
		if (RandomUtilities.RandomChance(purifyChanceAmount))
		{
			if (areaConfuse)
			{
				purifyAction.CastTargetAmountForAreaConfuse(target, amount, source);
			}
			else
			{
				purifyAction.CastTargetAmount(target, amount, source);
			}
		}
		else if (areaConfuse)
		{
			corruptAction.CastTargetAmountForAreaConfuse(target, amount, source);
		}
		else
		{
			corruptAction.CastTargetAmount(target, amount, source);
		}
	}

	private int BeforeDefaultCastGetPurifyChanceAmount(int amount, GameObject source)
	{
		bool flag = IsPlayerConfuse(source);
		int num = GetPurifyChanceAmount(flag);
		if (flag)
		{
			num = CheckConfuseModifyingEffectsAndGetPurifyChanceAmount(num, source);
			CheckBettingHighAustraAchievement(amount, source, num);
			playerEffects.IsPlayerIridescentLightActivateIt();
			criticalEffect.CriticalMultiplierConfuseAction = true;
		}
		return num;
	}

	private void AfterDefaultCast()
	{
		criticalEffect.CriticalIridescentLight = false;
		criticalEffect.CheckConfuseCriticalAndRemoveCriticalMultiplierConfuseEffect();
	}
}
